toolArgs.file_text:
@* Interactive star rating widget - uses InteractiveServer since it needs click handling *@
@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= SelectedRating ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  title="Rate @star star(s)">
                @(star <= SelectedRating ? "★" : "☆")
            </span>
        }
    </div>
    @if (ShowAverage)
    {
        <span class="rating-info">@AverageRating.ToString("F1") avg (@RatingCount ratings)</span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public bool ShowAverage { get; set; } = true;
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int SelectedRating { get; set; }
    private bool _submitted;

    private async Task Rate(int stars)
    {
        SelectedRating = stars;
        _submitted = true;
        if (OnRated.HasDelegate)
        {
            await OnRated.InvokeAsync(stars);
        }
    }
}

