                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService _recipeService { get; set; } = default!;

    private List<Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        // Capitalize first letter for display and lookup
        if (!string.IsNullOrEmpty(CategoryName))
        {
            CategoryName = char.ToUpper(CategoryName[0]) + CategoryName[1..];
            _recipes = _recipeService.GetRecipesByCategory(CategoryName);
        }
    }
}

@page "/recipe/{Id:int}"
@using RecipeSharing.Services
@using RecipeSharing.Models
@using RecipeSharing.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe") - Recipe Sharing</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (_recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@_recipe.Category.ToLower()">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            }
        </ol>
    </nav>

    @if (_recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@_recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@_recipe.Category</span>

        <div class="my-4">
            <h4>Rate this recipe</h4>
            <StarRating RecipeId="@_recipe.Id"
                        AverageRating="@_recipe.AverageRating"
                        RatingCount="@_recipe.RatingCount"
                        OnRated="HandleRating" />
        </div>

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                    <div class="card-body">
                        <ul class="list-unstyled">
                            @foreach (var ingredient in _recipe.Ingredients.Split('\n'))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService _recipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = _recipeService.GetRecipeById(Id);
    }

    private void HandleRating(int stars)
    {
        _recipeService.AddRating(Id, stars);
        _recipe = _recipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeSharing.Services
@using RecipeSharing.Models

<PageTitle>Submit a Recipe - Recipe Sharing</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Thank you for sharing "<strong>@_model.Title</strong>" with our community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => _model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in _recipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="6"
                               placeholder="Enter each ingredient on a new line" />
                <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="8"
                               placeholder="Enter each step on a new line" />
                <ValidationMessage For="() => _model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService _recipeService { get; set; } = default!;

    private RecipeFormModel _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };

        _recipeService.AddRecipe(recipe);
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(100, MinimumLength = 3)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

